#[path="../../../src-tauri/src/peer_data.rs"]pub mod peer_data;
#[path="../../../src-tauri/src/peer_wire.rs"]pub mod peer_wire;
#[path="../../../src-tauri/src/peer_files.rs"]pub mod peer_files;
#[cfg(test)]mod tests{
use super::peer_data::*;use rusqlite::Connection;use serde_json::json;
fn db()->Connection{let c=Connection::open_in_memory().unwrap();c.execute_batch("PRAGMA foreign_keys=ON;").unwrap();c.execute_batch(include_str!(concat!(env!("OUT_DIR"),"/schema.sql"))).unwrap();init(&c).unwrap();c}
fn all(c:&Connection)->Vec<Change>{let mut out=vec![];let mut at=0;loop{let p=page(c,at,None).unwrap();out.extend(p.changes);at=p.cursor;if p.done{break}}out}
fn clone_to(a:&Connection,b:&mut Connection){b.execute("DELETE FROM peer_stage",[]).unwrap();for ch in all(a){b.execute("INSERT INTO peer_stage(body)VALUES(?1)",[serde_json::to_string(&ch).unwrap()]).unwrap();}replace_from_stage(b).unwrap();}
#[test]fn initial_history_profile_and_fk(){let a=db();let mut b=db();a.execute_batch("INSERT INTO meds(id,kind,name)VALUES(kouros_id(),'vitamin','Fixture');INSERT INTO med_log(id,med_id,date,ts)SELECT kouros_id(),id,'2026-01-01',1 FROM meds;INSERT INTO settings VALUES('profile','{\"test\":true}');INSERT INTO settings VALUES('lock_enabled','1');").unwrap();b.execute("INSERT INTO settings VALUES('lock_enabled','0')",[]).unwrap();clone_to(&a,&mut b);assert_eq!(counts(&a).unwrap()["med_log"],counts(&b).unwrap()["med_log"]);assert_eq!(b.query_row("SELECT value FROM settings WHERE key='lock_enabled'",[],|r|r.get::<_,String>(0)).unwrap(),"0");assert!(b.query_row("SELECT value FROM settings WHERE key='profile'",[],|r|r.get::<_,String>(0)).unwrap().contains("test"));}
#[test]fn editing_and_deletion_are_idempotent(){let a=db();let mut b=db();a.execute("INSERT INTO habit_log VALUES('2026-01-01','sleep',1)",[]).unwrap();clone_to(&a,&mut b);let at=tick(&a).unwrap();a.execute("UPDATE habit_log SET val=2",[]).unwrap();let changes=page(&a,at,None).unwrap().changes;assert_eq!(apply(&mut b,&changes,false).unwrap(),1);assert_eq!(apply(&mut b,&changes,false).unwrap(),0);a.execute("DELETE FROM habit_log",[]).unwrap();apply(&mut b,&page(&a,at,None).unwrap().changes,false).unwrap();assert_eq!(counts(&b).unwrap()["habit_log"],0);}
#[test]fn offline_integer_ids_do_not_collide_after_import(){let a=db();let mut b=db();clone_to(&a,&mut b);let ca=tick(&a).unwrap();let cb=tick(&b).unwrap();a.execute("INSERT INTO surveys(id,kind,date,ts,answers)VALUES(kouros_id(),'t','2026-01-01',1,'{}')",[]).unwrap();b.execute("INSERT INTO surveys(id,kind,date,ts,answers)VALUES(kouros_id(),'t','2026-01-02',2,'{}')",[]).unwrap();let aa=page(&a,ca,None).unwrap().changes;let bb=page(&b,cb,None).unwrap().changes;let mut a=a;apply(&mut a,&bb,false).unwrap();apply(&mut b,&aa,false).unwrap();assert_eq!(counts(&b).unwrap()["surveys"],2);assert_eq!(counts(&a).unwrap()["surveys"],2);}
#[test]fn concurrent_same_row_converges_and_preserves_conflict(){let mut a=db();let mut b=db();a.execute("INSERT INTO habit_log VALUES('2026-01-01','t',1)",[]).unwrap();clone_to(&a,&mut b);let ca=tick(&a).unwrap();let cb=tick(&b).unwrap();a.execute("UPDATE habit_log SET val=2",[]).unwrap();b.execute("UPDATE habit_log SET val=3",[]).unwrap();let aa=page(&a,ca,None).unwrap().changes;let bb=page(&b,cb,None).unwrap().changes;apply(&mut a,&bb,false).unwrap();apply(&mut b,&aa,false).unwrap();assert_eq!(a.query_row("SELECT val FROM habit_log",[],|r|r.get::<_,i64>(0)).unwrap(),b.query_row("SELECT val FROM habit_log",[],|r|r.get::<_,i64>(0)).unwrap());assert!(a.query_row("SELECT count(*)FROM peer_conflicts",[],|r|r.get::<_,i64>(0)).unwrap()>0);}
#[test]fn invalid_initial_import_rolls_back_everything(){let mut b=db();b.execute("INSERT INTO habit_log VALUES('2026-01-01','keep',1)",[]).unwrap();let change=Change{t:"med_log".into(),k:vec![json!(999)],rev:1,actor:"a".repeat(32),deleted:false,row:Some(json!({"id":999,"med_id":98765,"date":"2026-01-01","ts":1,"servings":1.0}))};b.execute("INSERT INTO peer_stage(body)VALUES(?1)",[serde_json::to_string(&change).unwrap()]).unwrap();assert!(replace_from_stage(&mut b).is_err());assert_eq!(counts(&b).unwrap()["habit_log"],1);let muted:i64=b.query_row("SELECT muted FROM peer_control",[],|r|r.get(0)).unwrap();assert_eq!(muted,0);}
#[test]fn forbidden_tables_and_local_settings_rejected(){let mut b=db();let mut ch=Change{t:"peer_control".into(),k:vec![json!(1)],rev:1,actor:"a".repeat(32),deleted:true,row:None};assert!(apply(&mut b,&[ch.clone()],false).is_err());ch.t="settings".into();ch.k=vec![json!("hae")];assert!(apply(&mut b,&[ch],false).is_err());}
#[test]fn local_configuration_never_exported(){let a=db();for k in ["hae","lock_enabled","peer_token","strava_athlete"]{a.execute("INSERT INTO settings VALUES(?1,'private')",[k]).unwrap();}assert!(all(&a).iter().all(|c|c.t!="settings"||c.row.as_ref().unwrap()["value"]!="private"));}
}

#[cfg(test)]mod transport_tests{
use super::{peer_wire as w,peer_files as f,peer_data as d};use std::{net::{TcpListener,TcpStream},io::Write};
const CODE:&str="1234567890abcdef1234567890abcdef";
#[test]fn encrypted_payload_tampering_wrong_key_and_response_binding(){let e=w::seal(CODE,w::request_aad(),b"fictional profile").unwrap();assert!(!e.data.contains("fictional"));assert_eq!(w::open(CODE,w::request_aad(),&e).unwrap(),b"fictional profile");assert!(w::open("00000000000000000000000000000000",w::request_aad(),&e).is_err());assert!(w::open(CODE,&w::response_aad(&e.nonce),&e).is_err());let mut e=e;e.nonce="é".repeat(12);assert!(w::open(CODE,w::request_aad(),&e).is_err());}
#[test]fn real_socket_accepts_encrypted_http_only(){let l=TcpListener::bind("127.0.0.1:0").unwrap();let addr=l.local_addr().unwrap();let envelope=w::seal(CODE,w::request_aad(),b"test-only").unwrap();let bytes=serde_json::to_vec(&envelope).unwrap();let handle=std::thread::spawn(move||{let(mut s,_)=l.accept().unwrap();let e=w::read_http(&mut s).unwrap();assert_eq!(w::open(CODE,w::request_aad(),&e).unwrap(),b"test-only");});let mut s=TcpStream::connect(addr).unwrap();write!(s,"POST /kouros-sync/v1 HTTP/1.1\r\nContent-Length: {}\r\n\r\n",bytes.len()).unwrap();s.write_all(&bytes).unwrap();handle.join().unwrap();}
#[test]fn oversized_and_ambiguous_http_is_rejected(){for header in ["Content-Length: 999999999", "Content-Length: 1\r\nContent-Length: 1", "Transfer-Encoding: chunked"]{let l=TcpListener::bind("127.0.0.1:0").unwrap();let addr=l.local_addr().unwrap();let t=std::thread::spawn(move||{let(mut s,_)=l.accept().unwrap();assert!(w::read_http(&mut s).is_err())});let mut s=TcpStream::connect(addr).unwrap();write!(s,"POST /kouros-sync/v1 HTTP/1.1\r\n{header}\r\n\r\nx").unwrap();drop(s);t.join().unwrap();}}
#[test]fn only_lan_addresses_and_exact_pairing_codes(){assert!(w::private_ipv4("192.168.1.10").is_ok());for s in ["example.com","8.8.8.8","169.254.169.254","0.0.0.0","192.168.1.1/other"]{assert!(w::private_ipv4(s).is_err());}assert_eq!(w::normalized_code("1234 5678 90AB CDEF 1234-5678-90ab-cdef").unwrap(),CODE);assert!(w::normalized_code("123456").is_err());}
#[test]fn safe_attachments_and_checksum_before_commit(){let root=std::env::temp_dir().join(d::random_hex(16).unwrap());std::fs::create_dir_all(root.join("files")).unwrap();for path in ["files/../key","files/./a","files//a","files/C:\\x","../files/x","backups/a"]{assert!(f::safe_path(&root,path).is_err());}std::fs::write(root.join("files/test.fit"),b"fictional-data").unwrap();let(list,_)=f::manifest(&root,&serde_json::Value::Null).unwrap();let info=&list[0];f::write_chunk(&root,info,0,b"bad-data",true).unwrap_err();assert!(!f::safe_path(&root,&info.path).unwrap().exists());f::write_chunk(&root,info,0,b"fictional-data",true).unwrap();assert_eq!(f::hash(&f::safe_path(&root,&info.path).unwrap()).unwrap(),info.sha256);std::fs::remove_dir_all(root).unwrap();}
}
#[cfg(test)]mod regression_tests{
use super::peer_data::*;use rusqlite::Connection;use serde_json::json;
fn db()->Connection{let c=Connection::open_in_memory().unwrap();c.execute_batch(include_str!(concat!(env!("OUT_DIR"),"/schema.sql"))).unwrap();init(&c).unwrap();c}
#[test]fn renamed_natural_key_removes_previous_record(){let a=db();a.execute("INSERT INTO habit_log VALUES('2026-01-01','old',1)",[]).unwrap();let before=tick(&a).unwrap();a.execute("UPDATE habit_log SET key='new'",[]).unwrap();let p=page(&a,before,None).unwrap();assert!(p.changes.iter().any(|c|c.deleted&&c.k==vec![json!("2026-01-01"),json!("old")]));assert!(p.changes.iter().any(|c|!c.deleted&&c.k==vec![json!("2026-01-01"),json!("new")]));}
#[test]fn payload_limit_does_not_skip_records(){let a=db();let before=tick(&a).unwrap();let text="x".repeat(5*1024*1024);for i in 0..3{a.execute("INSERT INTO health_metrics(metric,date,ts,txt)VALUES('fixture','2026-01-01',?1,?2)",rusqlite::params![i.to_string(),text]).unwrap();}let mut cursor=before;let mut n=0;loop{let p=page(&a,cursor,None).unwrap();assert_eq!(p.changes.len(),1);assert!(p.cursor>cursor);cursor=p.cursor;n+=p.changes.len();if p.done{break}}assert_eq!(n,3);}
#[test]fn integer_leases_survive_reinitialization_and_js_precision(){let c=db();let one:i64=c.query_row("SELECT kouros_id()",[],|r|r.get(0)).unwrap();init(&c).unwrap();let two:i64=c.query_row("SELECT kouros_id()",[],|r|r.get(0)).unwrap();assert!(two>one);assert!(two<9_007_199_254_740_991);}
#[test]fn same_new_custom_exercise_has_same_identity_on_both_devices(){let a=db();let b=db();let aa:i64=a.query_row("SELECT kouros_exercise_id('Fixture exercise')",[],|r|r.get(0)).unwrap();let bb:i64=b.query_row("SELECT kouros_exercise_id('Fixture exercise')",[],|r|r.get(0)).unwrap();assert_eq!(aa,bb);assert!(aa<0);}
#[test]fn unknown_staged_table_preserves_previous_history(){let mut a=db();a.execute("INSERT INTO habit_log VALUES('2026-01-01','keep',1)",[]).unwrap();a.execute("INSERT INTO peer_stage(body)VALUES(?1)",[json!({"t":"secrets","k":[],"rev":1,"actor":"a".repeat(32),"deleted":false,"row":{}}).to_string()]).unwrap();assert!(replace_from_stage(&mut a).is_err());assert_eq!(counts(&a).unwrap()["habit_log"],1);}
}
#[cfg(test)]mod reference_tests{
use super::{peer_data as d,peer_files as f};use serde_json::json;use rusqlite::Connection;
#[test]fn referenced_attachment_must_arrive_and_match_before_history_is_applied(){let root=std::env::temp_dir().join(d::random_hex(16).unwrap());let source=root.join("source");let dest=root.join("dest");std::fs::create_dir_all(source.join("files")).unwrap();std::fs::create_dir_all(dest.join("files")).unwrap();std::fs::write(source.join("files/sample.fit"),b"fictional attachment").unwrap();let(list,_)=f::manifest(&source,&serde_json::Value::Null).unwrap();let info=&list[0];let c=Connection::open_in_memory().unwrap();c.execute("CREATE TABLE peer_stage(n INTEGER PRIMARY KEY,body TEXT)",[]).unwrap();let row=json!({"t":"activities","row":{"file_path":dest.join(&info.path).to_str().unwrap()}});c.execute("INSERT INTO peer_stage(body)VALUES(?1)",[row.to_string()]).unwrap();assert!(f::verify_stage(&dest,&c).is_err());f::write_chunk(&dest,info,0,b"fictional attachment",true).unwrap();f::verify_stage(&dest,&c).unwrap();std::fs::write(dest.join(&info.path),b"corrupted").unwrap();assert!(f::verify_stage(&dest,&c).is_err());std::fs::remove_dir_all(root).unwrap();}
}
#[cfg(test)]mod relative_path_tests{
use super::{peer_data as d,peer_files as f};use serde_json::json;
#[test]fn original_workout_and_lab_relative_paths_survive_both_directions(){let root=std::env::temp_dir().join(d::random_hex(16).unwrap());let source=root.join("source");let dest=root.join("dest");std::fs::create_dir_all(source.join("files/activities")).unwrap();std::fs::create_dir_all(source.join("files/labs")).unwrap();std::fs::create_dir_all(&dest).unwrap();std::fs::write(source.join("files/activities/fixture.fit"),b"workout fixture").unwrap();std::fs::write(source.join("files/labs/fixture.pdf"),b"document fixture").unwrap();let (list,_)=f::manifest(&source,&serde_json::Value::Null).unwrap();for (t,field,relative) in [("activities","file_path","files/activities/fixture.fit"),("lab_reports","file","labs/fixture.pdf")]{let mut ch=d::Change{t:t.into(),k:vec![json!(1)],rev:1,actor:"a".repeat(32),deleted:false,row:Some(json!({field:relative}))};f::wire_paths(&mut ch,&source,false).unwrap();let wire=ch.row.as_ref().unwrap()[field].as_str().expect("File association must not be cleared").to_string();assert!(wire.starts_with("@file:files/peer/"));f::wire_paths(&mut ch,&dest,true).unwrap();let value=ch.row.as_ref().unwrap()[field].as_str().unwrap();assert!(!std::path::Path::new(value).is_absolute());let actual=if t=="activities"{dest.join(value)}else{dest.join("files").join(value)};assert!(f::verify_changes(&dest,&[ch.clone()]).is_err());let info=list.iter().find(|x|wire==format!("@file:{}",x.path)).unwrap();let bytes=std::fs::read(source.join(&info.original)).unwrap();f::write_chunk(&dest,info,0,&bytes,true).unwrap();assert_eq!(std::fs::read(actual).unwrap(),bytes);f::verify_changes(&dest,&[ch.clone()]).unwrap();f::wire_paths(&mut ch,&dest,false).unwrap();assert_eq!(ch.row.as_ref().unwrap()[field].as_str().unwrap(),wire);}std::fs::remove_dir_all(root).unwrap();}
}
#[cfg(test)]mod original_alias_tests{
use super::{peer_data as d,peer_files as f};use serde_json::json;
#[test]fn matching_original_on_windows_is_materialized_before_accepting_mobile_edit(){let root=std::env::temp_dir().join(d::random_hex(16).unwrap());std::fs::create_dir_all(root.join("files/activities")).unwrap();std::fs::write(root.join("files/activities/fixture.fit"),b"original bytes").unwrap();let (manifest,cache)=f::manifest(&root,&serde_json::Value::Null).unwrap();let info=&manifest[0];let change=d::Change{t:"activities".into(),k:vec![json!("fixture")],rev:1,actor:"a".repeat(32),deleted:false,row:Some(json!({"file_path":info.path,"rpe":4}))};assert!(f::verify_changes(&root,&[change.clone()]).is_err());f::materialize_refs(&root,&[change.clone()],&cache).unwrap();f::verify_changes(&root,&[change]).unwrap();assert_eq!(std::fs::read(root.join(&info.path)).unwrap(),b"original bytes");assert_eq!(std::fs::read(root.join("files/activities/fixture.fit")).unwrap(),b"original bytes");std::fs::remove_dir_all(root).unwrap();}
}
